using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEngine.InputSystem.UI;
public class VoyageUI:MonoBehaviour {
 public RectTransform root;protected Font font;protected RectTransform safeArea;
 protected virtual void Awake(){font=Resources.Load<Font>("Voyage/PixelifySans");var go=new GameObject("Voyage UI",typeof(RectTransform),typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));go.transform.SetParent(transform,false);go.GetComponent<Canvas>().renderMode=RenderMode.ScreenSpaceOverlay;go.GetComponent<Canvas>().sortingOrder=2000;var s=go.GetComponent<CanvasScaler>();s.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;s.referenceResolution=new Vector2(1920,1080);s.screenMatchMode=CanvasScaler.ScreenMatchMode.Expand;root=go.GetComponent<RectTransform>();if(VoyageTouchInput.Enabled)safeArea=VoyageSafeArea.Create(root);if(!FindFirstObjectByType<EventSystem>())new GameObject("Menu input",typeof(EventSystem),typeof(InputSystemUIInputModule));}
 public RectTransform Rect(string name,Transform parent,Vector2 at,Vector2 size){var go=new GameObject(name,typeof(RectTransform));go.transform.SetParent(parent==root&&safeArea?safeArea:parent,false);var r=go.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=r.pivot=Vector2.one*.5f;r.anchoredPosition=at;r.sizeDelta=size;return r;}
 public Image Picture(string name,Transform parent,Vector2 at,Vector2 size,string asset){var r=Rect(name,parent,at,size);var im=r.gameObject.AddComponent<Image>();im.sprite=Resources.Load<Sprite>("Voyage/"+asset);if(im.sprite&&im.sprite.border.sqrMagnitude>0)im.type=Image.Type.Sliced;return im;}
 public Text Label(string name,Transform parent,Vector2 at,Vector2 size,string value,int pixels=32){var t=Rect(name,parent,at,size).gameObject.AddComponent<Text>();t.font=font;t.fontSize=pixels;t.text=value;t.alignment=TextAnchor.MiddleCenter;t.color=new Color(1,.94f,.77f);t.raycastTarget=false;return t;}
 public Button Button(string name,Transform parent,Vector2 at,string label,UnityEngine.Events.UnityAction click){var im=Picture(name,parent,at,new Vector2(500,100),"button");var b=im.gameObject.AddComponent<Button>();b.transition=Selectable.Transition.SpriteSwap;b.spriteState=new SpriteState{highlightedSprite=Resources.Load<Sprite>("Voyage/button_hover"),selectedSprite=Resources.Load<Sprite>("Voyage/button_hover"),pressedSprite=Resources.Load<Sprite>("Voyage/button_pressed")};Label("Label",im.transform,Vector2.zero,new Vector2(430,65),label);b.onClick.AddListener(click);return b;}
}
